import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Hearth System Design","description":"Hearth product positioning, overall design, technology choices, and module map.","frontmatter":{"title":"Hearth System Design","description":"Hearth product positioning, overall design, technology choices, and module map.","outline":[2]},"headers":[],"relativePath":"en/design/index.md","filePath":"en/design/index.md","lastUpdated":1794373393000}'),o={name:"en/design/index.md"};function s(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="hearth-system-design" tabindex="-1">Hearth System Design <a class="header-anchor" href="#hearth-system-design" aria-label="Permalink to &quot;Hearth System Design&quot;">​</a></h1><p class="lead">Hearth is a single-user, self-hosted personal Agent OS for long-running work. It turns intent into durable, auditable, and recoverable tasks, with models, tools, and external systems working through one task path.</p><h2 id="product-positioning-and-goals" tabindex="-1">Product Positioning and Goals <a class="header-anchor" href="#product-positioning-and-goals" aria-label="Permalink to &quot;Product Positioning and Goals&quot;">​</a></h2><p>Hearth serves one primary user, with a small number of trusted collaborators who may review or approve work. Personal files, credentials, memory, and devices stay under the user&#39;s control by default. Cloud models, remote isolation, and sync services are optional capabilities, not a reason to hand over all data.</p><p>The product is organized around tasks, not chat history. The user needs to know what the system is doing, why it needs attention, what was delivered, and where to recover after a failure. Models, tools, and execution environments can change; task state, authority, evidence, and external receipts must remain.</p><p>Phase one did not start with all personal work. It used 15 cross-industry tasks with verifiable results to establish the first complete path from input to delivery, and 13 passed, meeting the 10/15 hard gate. It does not try to cover all personal work, but it requires document processing, web research, engineering collaboration, data/finance, customer support, recruiting, education, and marketing to share one task, approval, artifact, and recovery system. Once that foundation is reliable, Hearth expands sources, external writes, desktop operation, proactive service, memory, and multi-device use; those extensions currently have code closures only, and real acceptance lives in <a href="/hearth-os/en/delivery/">Delivery</a>.</p><p><strong>Explicit non-goals:</strong> enterprise multi-tenancy, a public agent marketplace, unapproved high-risk automation, a foundation-model race, and a tool that requires daily maintenance of prompts, plugins, and workflows.</p><p>Work is not done because a model says so. It needs a user-visible result, reviewable evidence, explicit open items, and approval plus a receipt for external effects.</p><h2 id="overall-design-and-task-path" tabindex="-1">Overall Design and Task Path <a class="header-anchor" href="#overall-design-and-task-path" aria-label="Permalink to &quot;Overall Design and Task Path&quot;">​</a></h2><p>Hearth uses one path for every piece of work: an entrance receives the request, the control layer decides whether it deserves action, the task layer holds the goal and state, executors do the work, approval and receipts protect external effects, and verification decides whether to finish or ask for help.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th><th>Does not own</th></tr></thead><tbody><tr><td>Entrances and experience</td><td>Messages, files, pages, timers, task cards, approvals, artifacts, and takeover</td><td>Deciding execution or writing state directly</td></tr><tr><td>Control and authority</td><td>Ignore, observe, suggest, or create; scope, risk, and autonomy</td><td>Running tools or holding long-lived raw credentials</td></tr><tr><td>Tasks and durable execution</td><td>Goals, work units, attempts, budgets, checkpoints, and recovery</td><td>Deciding business authority or writing externally</td></tr><tr><td>Executors and routing</td><td>Choosing the right capability, risk level, cost, and device</td><td>Expanding its own authority or bypassing approval</td></tr><tr><td>Approval and external effects</td><td>Preview, authorization, idempotent execution, receipts, reconciliation, and takeover</td><td>Deciding whether the task is worth doing</td></tr><tr><td>Runtime and safety</td><td>Workspaces, isolation, network, credentials, sensitive data, and device boundaries</td><td>Replacing product-level risk judgment</td></tr><tr><td>Memory and evolution</td><td>Correctable context and reusable methods, promoted only after evaluation</td><td>Becoming the source of truth or self-expanding</td></tr><tr><td>Evaluation and cost</td><td>Real tasks, verifiers, baselines, and cost metrics</td><td>Replacing acceptance with a demo</td></tr></tbody></table><p>Every fact is recorded first. Interfaces, notifications, and reports are rebuilt from that record. The early system uses one process, one writer, and a local database; it does not split into microservices for scale that does not exist yet. Work survives restarts, sleep, and network loss. One effective executor advances a work unit at a time, and late results cannot overwrite newer state.</p><p>An external action is more than a model calling a tool. Hearth previews the action, checks authority and approval, executes with a repeatable identifier, and stores a receipt. An uncertain result is reconciled before retry. If the result cannot be confirmed or the risk is too high, Hearth pauses and hands control to the user.</p><h2 id="technology-choices" tabindex="-1">Technology Choices <a class="header-anchor" href="#technology-choices" aria-label="Permalink to &quot;Technology Choices&quot;">​</a></h2><p>Technology follows system constraints, not language preference. Hearth must run for years, share protocols across entrances, integrate tools without losing control, and be maintainable by a small team.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Choice</th><th>Why</th></tr></thead><tbody><tr><td>Primary language</td><td>TypeScript</td><td>Control, tasks, command line, web, and adapters share concepts and validation, reducing protocol drift</td></tr><tr><td>Service runtime</td><td>Node.js 22.13+</td><td>Fits high-I/O orchestration and event delivery; one process, one writer; document work uses built-in <code>node:sqlite</code></td></tr><tr><td>Local storage</td><td>SQLite WAL</td><td>Enough for a single-user, local-first, single-writer system, with simple backup and migration</td></tr><tr><td>Web interface</td><td>React and Vite</td><td>Fits task cards, approvals, artifacts, and live state; the PWA shell and mobile navigation exist, while phone pairing, system push, and remote takeover remain unaccepted</td></tr><tr><td>Live updates</td><td>Server-Sent Events</td><td>Simpler than a two-way persistent connection for server-side state changes</td></tr><tr><td>Documents and data</td><td>Server-side TypeScript</td><td><code>cheerio</code>, <code>pdfjs-dist</code>, <code>mammoth</code>, <code>exceljs</code>, and <code>docx</code> read HTML, PDF, DOCX, XLSX, and CSV and write XLSX/CSV/DOCX in-process, without a second business protocol</td></tr><tr><td>Native boundary</td><td>PowerShell + Node bridge</td><td>The Windows helper owns window observation, UIA, and input; Rust appears only when a single binary or stronger isolation becomes a hard constraint</td></tr></tbody></table><p>TypeScript is the language; Node.js is the runtime. They are not alternatives. TypeScript provides development-time types, while Node.js provides files, network, processes, and timers. External input and stored data still need runtime validation.</p><p>TypeScript wins mainly because of shared protocols and integration speed. Tasks, approvals, artifacts, receipts, and execution events appear in the service, command line, web interface, and tests. One set of types and validation reduces drift. Hearth is mostly orchestration and waiting, not sustained large-scale computing, so Node.js is sufficient at personal scale.</p><p>Rust is not the primary language because the bottleneck is product boundaries, protocol consistency, recovery, and authority judgment, not raw speed. Desktop work first validates real interaction with PowerShell plus a Node bridge; Rust expands only if a single binary, stronger isolation, or device resources become hard constraints. Go and Python are not part of the business stack today; document parsing already runs in the TypeScript server, avoiding a second runtime in the first phase.</p><p>The frontend uses React and Vite without a second server-rendered runtime. Task state comes from the local service projection; the browser renders and sends commands. The first phase does not introduce microservices or network boundaries just to look complete. The PWA shell, mobile bottom navigation, and offline application shell exist, but phone pairing, iOS/Android installation, system push, and remote takeover remain unaccepted parts of <a href="/hearth-os/en/delivery/stage-4.html">Phase 4</a>.</p><h2 id="module-map-and-key-boundaries" tabindex="-1">Module Map and Key Boundaries <a class="header-anchor" href="#module-map-and-key-boundaries" aria-label="Permalink to &quot;Module Map and Key Boundaries&quot;">​</a></h2><p>The fifteen modules below are parallel design notes. Together they cover the product from the first entrance to long-running operation, without following a code directory layout.</p><table tabindex="0"><thead><tr><th>Module</th><th>What it solves first</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/design/experience.html">Entrances and Experience</a></td><td>Let the user know what the system is doing, when attention is needed, and where results live</td></tr><tr><td><a href="/hearth-os/en/design/tasks.html">Tasks and Durable Execution</a></td><td>Keep work alive across restarts, sleep, and failure, with evidence and recovery</td></tr><tr><td><a href="/hearth-os/en/design/goals-and-evidence.html">Goals, Completion, and Evidence</a></td><td>Turn goals into acceptance contracts and decide completion from evidence rather than model self-assessment</td></tr><tr><td><a href="/hearth-os/en/design/control.html">Control and Authority</a></td><td>Decide when to observe, suggest, execute, or stop, within explicit authority</td></tr><tr><td><a href="/hearth-os/en/design/executors.html">Executors and Routing</a></td><td>Use specialized capabilities instead of one universal model</td></tr><tr><td><a href="/hearth-os/en/design/native-agent-runtime.html">Native Agent Runtime</a></td><td>A self-built general execution kernel that unifies model protocols, tools, compaction, skills, delegation, worktrees, MCP, budgets, and checkpoints</td></tr><tr><td><a href="/hearth-os/en/design/delegation-and-sandbox.html">Delegation, Handoff, and Sandboxing</a></td><td>Delegate bounded work, continue with handoff packets, and enforce path, network, and credential boundaries</td></tr><tr><td><a href="/hearth-os/en/design/effects.html">Approvals, Takeover, and External Effects</a></td><td>Make sends, writes, deletes, and publishes previewable, authorized, and reconcilable</td></tr><tr><td><a href="/hearth-os/en/design/safety.html">Runtime and Safety</a></td><td>Limit real-world impact with isolation, least privilege, and credential boundaries</td></tr><tr><td><a href="/hearth-os/en/design/storage.html">Storage and Context Architecture</a></td><td>Unify facts, model bindings, and handoff watermarks with SQLite, content blobs, and task context</td></tr><tr><td><a href="/hearth-os/en/design/personal-context.html">Personal Context and Attention</a></td><td>Use a personal ontology, context packs, memory recall, and interruption budgets to decide what the agent knows and when to speak</td></tr><tr><td><a href="/hearth-os/en/design/memory.html">Memory and Capability Evolution</a></td><td>Accumulate context and methods while staying correctable, forgettable, and reversible</td></tr><tr><td><a href="/hearth-os/en/design/evaluation.html">Evaluation and Cost</a></td><td>Prove reliability and cost with real tasks instead of demos</td></tr><tr><td><a href="/hearth-os/en/design/operations.html">Multi-device and Long-running Operation</a></td><td>Keep one set of tasks, authority, and data consistent across devices over time</td></tr><tr><td><a href="/hearth-os/en/design/agent-reference-patterns.html">Agent Reference Patterns</a></td><td>Record borrowed patterns and trade-offs instead of treating an external framework as the product architecture</td></tr></tbody></table><p>The non-negotiable boundaries are: every interface is rebuilt from a record; each state has one write authority; goal-backed tasks require acceptance criteria and a completion verdict; external actions have approval or an explicit exemption plus a reconcilable receipt; executors never see long-lived raw credentials; handoffs can narrow authority but never expand it; every task has a budget, deadline, and cancellation path; memory has provenance, sensitivity, and forgetting rules; method changes require evaluation, canary, promotion, and rollback.</p>',24)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
